INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES ('CGNC156', 'RIONEGRO', 'VILLAGOMEZ', 'CARACTERIZACION: GESTION Y ACOMPAÑAMIENTO. 150 USUARIOS', 'SERVICIOS', 'GASIFICACION', 'CARACTERIZACION: GESTION Y ACOMPAÑAMIENTO. 150 USUARIOS PARA IDENTIFICAR LA ALTERNATIVA DE CONEXION', NULL, 'CONECTAR 16.000 USUARIOS NUEVOS AL SERVICIO DE GAS COMBUSTIBLE PARA EL CIERRE DE BRECHAS.', true, true, false, 'NO', 'MEDIA', 'COMPLETADO', 3936051026.00, 1050000000.00, NULL, NULL, 700000000.00, 'DEPARTAMENTO - MUNICIPIO - OPERADOR', 'SECRETARIA DE ENERGIAS Y MINERIA SOSTENIBLE', 'YAVEGAS S.A. E S.P.', 'CONVENIO INTERADMINISTRATIVO', 'SMEG-CDCASO-035-2024', 'AUNAR ESFUERZOS TÉCNICOS Y FINANCIEROS PARA AMPLIAR LA COBERTURA DEL SERVICIO PÚBLICO DE GAS NATURAL DOMICILIARIO POR REDES MEDIANTE LA CONEXIÓN E INSTALACIÓN DE RED INTERNA A LOS DOMICILIOS DE LOS HABITANTES DE LAS VEREDAS Y CENTROS POBLADOS DE LOS MUNICIPIOS DE TOPAIPI, EL PEÑON Y VILLAGOMEZ.', '175000000', 'CONEXIÓN E INSTALACIÓN DE RED INTERNA A 70 USUARIOS PARA EL MUNICIPIO DE VILLAGOMEZ', '2024-11-29', '2025-09-28', 'MARZO: ESTO ES UN CONVENIO EN CONJUNTO CON EL PEÑON Y TOPAIPÍ EL CUAL SE ENCUETRA EN EJECUCION CON VIGENCIA HASTA EL 28 DE JULIO, SE ENCUENTRA EN REVISION PRORROGA POR ADICION DE POTENCIALES USUARIOS. LA EJECUCIÓN PARA ESTE MUNICIPIO YA SE ENCUENTRA TERMINADA Y SE ENCUENTRA EN TRÁMITE PARA PAGO. ABRIL: SE VIENE ADELANTANDO CON NORMALIDAD PRESENTA UN AVANCE EN TENDIDO DE REDES DE 60% Y DE LAS INSTALACIONES INTERNAS UN AVANCE DEL 15%. SE ADELANTA INSPECCIÓN Y VERIFICACIÓN DE AVANCE DE OBRA. LAS ALCALDÍAS SOLICITARON LA ADICIÓN DE APROXIMADAMENTE 140 POTENCIALES NUEVOS USUARIOS, QUE SE ENCUENTRAN EN ESTUDIO DE VIABILIDAD TÉCNICA POR PARTE DE LA EMPRESA PRESTADORA DEL SERVICIO. EL PROYECTO CONTINÚA CON LAS LABORES PROGRAMADAS, SE HAN INSTALADO 39 KILÓMETROS DE RED CONECTANDO A 42 USUARIOS LOS CUALES ESTÁN A LA ESPERA DE DARLES EL SERVICIO. MAYO: TOPAIPÍ - VILLA GÓMEZ (INCLUYE EL PEÑÓN): EL PROYECTO SE ENCUENTRA AL 100%, HUBO UN AVANCE EN REDES DE 12.1KM FALTANTES PARA COMPLETAR LOS 51.1 KM, SE ENCUENTRAN PROGRAMADOS 701 USUARIOS INCLUYENDO LA ADICIÓN DEL CONVENIO, SE INSTALAN 90 NUEVOS USUARIOS DE LA ADICIÓN Y SE CONTINÚAN CON LOS 42 USUARIOS DE LA SEMANA ANTERIOR. EL BENEFICIO TOTAL PARA EL CASO DE VILLAGOMEZ ES DE $439.222.011. MARZO: SE VIENE ADELANTANDO CON NORMALIDAD Y PRESENTA UN AVANCE EN TENDIDO DE REDES DE 60% Y DE LAS INSTALACIONES INTERNAS DE 15% ABRIL: EL PROYECTO CONTINÚA CON LAS LABORES PROGRAMADAS, SE HAN INSTALADO 39 KILÓMETROS DE RED CONECTANDO A 42 USUARIOS LOS CUALES ESTÁN A LA ESPERA DE DARLES EL SERVICIO. MAYO: TOPAIPÍ - VILLA GÓMEZ (INCLUYE EL PEÑÓN): EL PROYECTO SE ENCUENTRA AL 100%, HUBO UN AVANCE EN REDES DE 12.1KM FALTANTES PARA COMPLETAR LOS 51.1 KM, SE ENCUENTRAN PROGRAMADOS 701 USUARIOS INCLUYENDO LA ADICIÓN DEL CONVENIO, SE INSTALAN 90 NUEVOS USUARIOS DE LA ADICIÓN Y SE CONTINÚAN CON LOS 42 USUARIOS DE LA SEMANA ANTERIOR', NULL, NULL, NULL, NULL, 'EN LIQUIDACION', 187, 'MINAS', 'COMPROMISO DEL GOBERNADOR - ESTRATÉGICO', 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.7090102&isFromPublicArea=True&isModal=False', '(BUENA VISTA:), (POTOSI:)', 100.00, 7921.00);
