INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES ('CGNC604', 'SUMAPAZ', 'GRANADA', 'AMPLIACION DE COBERTURA EN CONEXION DE GAS DOMICILIARIO EN EL MUNICIPIO. VIABILIDAD DE COFINANCIACION DE CARGOS DE CONEXION Y/O SUBSIDIOS Y/O RED', 'SERVICIOS', 'GASIFICACION', 'AMPLIACION DE COBERTURA EN CONEXION DE GAS DOMICILIARIO EN EL MUNICIPIO. VIABILIDAD DE COFINANCIACION DE CARGOS DE CONEXION Y/O SUBSIDIOS Y/O RED 
  310 USUARIOS', NULL, 'CONECTAR 16.000 USUARIOS NUEVOS AL SERVICIO DE GAS COMBUSTIBLE PARA EL CIERRE DE BRECHAS.', true, true, false, 'NO', 'MEDIA', 'EN CURSO', NULL, 4572000000.00, NULL, NULL, NULL, 'DEPARTAMENTO', 'SECRETARIA DE ENERGIAS Y MINERIA SOSTENIBLE', 'YAVEGAS S.A. E S.P.', 'CONVENIO INTERADMINISTRATIVO', 'SEMS-ES-CA-0302025', 'AUNAR ESFUERZOS TÉCNICOS Y FINANCIEROS PARA AMPLIAR LA COBERTURA DEL SERVICIO DE GAS COMBUSTIBLE POR REDES, A TRAVÉS DE LA FINANCIACIÓN DEL CARGO POR CONEXIÓN Y LA RED INTERNA, PARA USUARIOS DE LAS VEREDAS DEL MUNICIPIO DE GRANADA', '1621500516', 'CONEXIÓN Y REDES INTERNAS, PARA 254 USUARIOS DE LAS VEREDAS DEL MUNICIPIO DE GRANADA', '2025-05-09', '2025-12-31', 'MARZO: SE RECIBE LA DOCUMENTACIÓN POR PARTE DE YAVEGAS SA ESP, PARA INICIAR LA EVALUACIÓN TÉCNICA POR PARTE DE LA SEMS PARA PROYECTOS DE EXPANSIÓN DE COBERTURA. MAYO Y JUNIO: 6 DE JUNIO, VISITA DE SOCIALIZACIÓN AL MUNICIPIO DE GRANADA DONDE SE FIRMÓ EL CONVENIO DE SUMINISTRO DE GAS CONVENIO SEMS-ES-CA-0302025 DE 254 USUARIOS (LA SUSCRIPCIÓN DEL CONVENIO SE REPORTÓ EN LA SEMANA DEL 13 DE MAYO). MAYO: EL 13 DE MAYO SE REALIZÓ LA FIRMA DE UN CONVENIO QUE BUSCA EXTENDER LA COBERTURA DEL SERVICIO DE GAS COMBUSTIBLE POR REDES, BENEFICIANDO A 254 HOGARES EN EL MUNICIPIO DE GRANADA DE LAS VEREDAS SANTA HELENA, GUASIMAL, LA PLAYITA, SAN RAIMUNDO Y SAN JOSÉ, MEDIANTE LA FINANCIACIÓN DEL CARGO POR CONEXIÓN, LA RED INTERNA Y LA CONSTRUCCIÓN DE 19,45 KILÓMETROS DE RED DE DISTRIBUCIÓN, CON UNA INVERSIÓN TOTAL DE 1.621,5 MILLONES DE PESOS (DEPARTAMENTO Y OTRAS FUENTES). EL 27 DE MAYO SE REALIZÓ LA FIRMA DEL CONVENIO DE ASOCIACIÓN NO. SEMS-ES-CA- 027-2025 QUE BUSCA AUNAR ESFUERZOS ECONÓMICOS, ADMINISTRATIVOS Y OPERATIVOS, PARA BRINDAR ASISTENCIA TÉCNICA E IMPLEMENTACIÓN DE SOLUCIONES ENERGÉTICAS RENOVABLES Y MEJORES PRÁCTICAS AMBIENTALES Y PRODUCTIVAS EN EL DEPARTAMENTO DE CUNDINAMARCA, MEDIANTE EL USO DE BIOGÁS. ENTRE PORKCOLOMBIA Y LAS SECRETARIAS SEMS, BIENESTAR VERDE Y AGROCAMPESINADO, PARA ATENDER HASTA 35 FINCAS PORCÍCOLAS CON UN APORTE DE LA SECRETARÍA DE $100.000.000 PARA UN TOTAL DE APORTES DEL PROYECTO DE $310.000.000. MARZO: SE CONTEMPLAN MESAS DE TRABAJO ADICIONALES PARA REVISIÓN DE LOS REQUISITOS EN LA PRESENTACIÓN DEL ESTUDIO Y EVALUACIÓN DE PROYECTOS DE EXPANSIÓN DE GAS 254 USUARIOS Y PIDEN $ 457, 200 MILLONES. ABRIL Y MAYO: EL 13 DE MAYO SE REALIZÓ LA FIRMA DE UN CONVENIO QUE BUSCA EXTENDER LA COBERTURA DEL SERVICIO DE GAS COMBUSTIBLE POR REDES, BENEFICIANDO A 254 HOGARES EN EL MUNICIPIO DE GRANADA DE LAS VEREDAS SANTA HELENA, GUASIMAL, LA PLAYITA, SAN RAIMUNDO Y SAN JOSÉ, MEDIANTE LA FINANCIACIÓN DEL CARGO POR CONEXIÓN, LA RED INTERNA Y LA CONSTRUCCIÓN DE 19,45 KILÓMETROS DE RED DE DISTRIBUCIÓN, CON UNA INVERSIÓN TOTAL DE 1.621,5 MILLONES DE PESOS (DEPARTAMENTO Y OTRAS FUENTES). MAYO: EL 27 DE MAYO SE REALIZÓ LA FIRMA DEL CONVENIO DE ASOCIACIÓN NO. SEMS-ES-CA- 027-2025 QUE BUSCA AUNAR ESFUERZOS ECONÓMICOS, ADMINISTRATIVOS Y OPERATIVOS, PARA BRINDAR ASISTENCIA TÉCNICA E IMPLEMENTACIÓN DE SOLUCIONES ENERGÉTICAS RENOVABLES Y MEJORES PRÁCTICAS AMBIENTALES Y PRODUCTIVAS EN EL DEPARTAMENTO DE CUNDINAMARCA, MEDIANTE EL USO DE BIOGÁS. ENTRE PORKCOLOMBIA Y LAS SECRETARIAS SEMS, BIENESTAR VERDE Y AGROCAMPESINADO, PARA ATENDER HASTA 35 FINCAS PORCÍCOLAS CON UN APORTE DE LA SECRETARÍA DE $100.000.000 PARA UN TOTAL DE APORTES DEL PROYECTO DE $310.000.000.', NULL, NULL, NULL, NULL, NULL, 207, 'MINAS', 'COMPROMISO DEL GOBERNADOR - ESTRATÉGICO', 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.8093013&isFromPublicArea=True&isModal=False', '(SANTA HELENA:), (GUASIMAL:), (LA PLAYITA:), (SAN RAIMUNDO:) y (SAN JOSÉ:)', NULL, 0.00);
