INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES (NULL, 'RIONEGRO', 'TOPAIPI', 'ESTUDIOS Y DISEÑOS DE PROYECTO DE AMPLIACION DE COBERTURA DE ENERGIA ELECTRICA', 'SERVICIOS', 'ENERGIA ELECTRICA', 'ESTUDIOS Y DISEÑOS DE PROYECTO DE AMPLIACION DE COBERTURA DE ENERGIA ELECTRICA', NULL, 'CONECTAR 1.200 VIVIENDAS AL SERVICIO DE ENERGÍA ELÉCTRICA QUE NO CUENTEN ACTUALMENTE CON EL SERVICIO PARA CONTRIBUIR AL CIERRE DE BRECHAS.', true, true, false, 'NO', 'MEDIA', 'EN CURSO', NULL, 5261117940.00, NULL, NULL, 5112946990.00, 'DEPARTAMENTO - OPERADOR', 'SECRETARIA DE ENERGIAS Y MINERIA SOSTENIBLE', 'ENEL COLOMBIA S.A. ESP', 'CONVENIO INTERADMINISTRATIVO', 'SEMS-ES-CA-028-2025', 'AUNAR ESFUERZOS ENTRE LA SECRETARÍA DE ENERGÍAS Y MINERÍA SOSTENIBLES DEL DEPARTAMENTO DE CUNDINAMARCA Y ENEL COLOMBIA S.A. E.S.P., PARA LA CONSTRUCCIÓN DE REDES ELÉCTRICAS EN ZONA RURAL DE LOS MUNICIPIOS DEL DEPARTAMENTO DE CUNDINAMARCA.', '0', 'CONSTRUCCIÓN DE INFRAESTRUCTURA DE REDES ELÉCTRICAS DE MEDIA Y BAJA TENSIÓN PARA 65 USUARIOS EN LA ZONA RURAL DE LOS MUNICIPIOS DE TOPAIPÍ Y VIOTÁ', '2025-05-07', '2025-12-31', 'ETAPA PRECONTRACTUAL PARA SUSCRIBIR UN CONVENIO PARA BENEFICIAR 65 USUARIOS DE LOS MUNICIPIOS DE TOPAIPÍ (36) Y VIOTÁ (29). TOTAL PROYECTO $1.516 MILLONES ESTIMANDO APORTES DEL OPERADOR Y DEPARTAMENTO, ASÍ:
 ENEL COLOMBIA S.A. E.S.P. $749 MILLONES EQUIVALENTE AL 49,91%
 GOBERNACIÓN DE CUNDINAMARCA $767 MILLONES EQUIVALENTE AL 50,09%
 SE REALIZÓ LA ESTRUCTURACIÓN Y TRÁMITE DEL PROYECTO ESPECÍFICO ANTE EL BANCO DEPARTAMENTAL DE PROYECTOS, OBTENIENDO SU INSCRIPCIÓN BAJO EL BPIN 202500000018956 - CONSTRUCCIÓN DE REDES ELÉCTRICAS DE MEDIA Y BAJA TENSIÓN EN ZONA RURAL DE LOS MUNICIPIOS DE TOPAIPÍ Y VIOTÁ DEL DEPARTAMENTO DE CUNDINAMARCA. SE OBTUVO EL CONCEPTO PRECONTRACTUAL DE SECRETARÍA DE PLANEACIÓN Y CDP, JUNTO CON LA ELABORACIÓN DE LOS DOCUMENTOS PRECONTRACTUALES: ESTUDIOS PREVIOS, ANÁLISIS DE SECTOR Y MINUTA; RADICADOS LOS DOCUMENTOS PRECONTRACTUALES ANTE EL COMITÉ DE CONTRATACIÓN, EL CUAL REALIZÓ EL 4 DE ABRIL DE 2025 EL AVAL PARA LA SUSCRIPCIÓN DEL CONVENIO ENTRE LA SEMS Y EL OPERADOR DE RED ENEL.
 EL 23 DE ABRIL DE 2025 SE REALIZÓ UNA REUNIÓN TÉCNICA Y JURÍDICA ENTRE LA SECRETARÍA DE ENERGÍAS Y MINERÍA SOSTENIBLE Y ENEL COLOMBIA S.A. E.S.P., CON EL OBJETIVO DE REVISAR / COMPLEMENTAR / RESPONDER Y CONCLUIR SUGERENCIAS PROPUESTAS POR PARTE DEL OPERADOR DE RED A LA MINUTA, QUEDANDO EL COMPROMISO QUE EL ÁREA JURÍDICA DE ENEL PROCEDERÁ EN LOS PRÓXIMOS DÍAS A DARNOS EL VISTO BUENO PARA PROCEDER A LA SUSCRIPCIÓN DEL CONVENIO.
 MAYO: SE SUSCRIBIÓ UN NUEVO CONVENIO SEMS-ES-CA-028-2025 CON ENEL, PARA BENEFICIAR 65 USUARIOS DE LOS MUNICIPIOS DE TOPAIPÍ (36) Y VIOTÁ (29), INICIATIVA QUE CUENTA CON UNA INVERSIÓN TOTAL DE $1.516 MILLONES DE PESOS CON UNA ESTIMACIÓN DE APORTES DE $767 MILLONES DE PESOS POR PARTE DE LA GOBERNACIÓN DE CUNDINAMARCA (50,09%) Y DE $749 MILLONES, EQUIVALENTE A UN 49,91% POR PARTE DE ENEL COLOMBIA S.A. SE REALIZÓ LA FIRMA PROTOCOLARIAMENTE DEL CONVENIO SEMS-ES-CA-028-2025, SE APROBARON LAS PÓLIZAS Y SE FIRMÓ ACTA DE INICIO.', NULL, false, NULL, NULL, 'OCTUBRE: EN PROCESO DE MODIFICATORIO DEL CONVENIO 028 DEBIDO A NUEVAS NORMAS ESTABLECIDAS POR EL OPERADOR DE RED. UNA VEZ FINALIZADA ESTA MODIFICACIÓN DEL CONVENIO, SE PROCEDE A ACTUALIZAR EJECUCIÓN FÍSICA Y FINANCIERA.', 225, 'MINAS', NULL, 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.8024616&isFromPublicArea=True&isModal=False', '(ALTO DE MICOS: (4.91413)° latitud y (-74.40417)° longitud ), (BERMEJAL:), (BUNQUE:), (MUCHIPAY:), (NACOPAY:), (NARANJAL:), (PALMICHAL:), (PAPATAS:), (PISCO GRANDE:), ( SAN ANTONIO DE AGUILERA: ), (SAN MARTIN:), (SUARAS: )', 0.00, 0.00);
