INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES ('CGNC957', 'UBATE', 'GUACHETA', 'TERMINACION DE LA CONSTRUCCION DEL CENTRO MINERO-ENERGETICO DE CUNDINAMARCA. DOTACION Y PUESTA EN MARCHA', 'INFRAESTRUCTURA ENERGETICA', 'CENTRO MINERO-ENERGETICO', 'TERMINACION DE LA CONSTRUCCION DEL CENTRO MINERO-ENERGETICO DE CUNDINAMARCA. DOTACION Y PUESTA EN MARCHA  $ 16.655.165.706 * 15.300 MILLONES OFICIALES', NULL, 'AMPLIAR Y DOTAR EL CENTRO MINERO-ENERGÉTICO DE CUNDINAMARCA.', true, true, true, 'NO', 'MEDIA', 'EN CURSO', 16655165706.00, NULL, NULL, NULL, NULL, 'Departamento - SGR', 'SECRETARIA DE ENERGIAS Y MINERIA SOSTENIBLE', 'Consorcio Centro Minero y Consorcio Sakkor', 'CONTRATO INTERADMINISTRATIVO', 'SMEG-CM-026-2023.', 'INTERVENTORÍA TÉCNICA, ADMINISTRATIVA, JURÍDICA, FINANCIERA Y AMBIENTAL DE LA CONSTRUCCIÓN DEL CENTRO MINERO - ENERGÉTICO DE CUNDINAMARCA', '15.300.851.909', NULL, NULL, NULL, 'MARZO: INICIA EL TRÁMITE PARA REALIZAR EL AJUSTE AL PROYECTO DE REGALÍAS Y POSTERIORMENTE REALIZAR LOS ACTOS ADMINSITRATIVOS CORRESPONDIENTES PARA ADICIONAR LOS RECURSOS PROPIOS DEL AJUSTE Y PRORROGA EN TIEMPO. EL VALOR A ADICIONAR SERÁ DE 1.300 MILLONES. ABRIL: LA ENTIDAD SE ENCUENTRA TERMINANDO LA CONSTRUCCIÓN DEL CENTRO MINERO ENERGÉTICO DE CUNDINAMARCA CON FECHA DE POSIBLE ENTREGA PARA EL 31 DE MAYO DE 2025, A LA FECHA SE CUENTA CON UN AVANCE APROXIMADO DEL 64%. EN ESTE TÉRMINO SE ESTÁ ADELANTANDO GESTIONES CON EL SERVICIO NACIONAL DE APRENDIZAJE – SENA, PARA QUE ESTA SEA LA ENTIDAD QUE ASUME LA OPERACIÓN MANTENIMIENTO Y FUNCIONAMIENTO DEL CENTRO. HASTA EL MOMENTO EL SENA SE ENCUENTRA GESTIONANDO 2.200 MILLONES DE PESOS PARA LA DOTACIÓN DE GRAN PARTE DE LOS ESPACIOS DE AULAS Y LABORATORIOS. DE ESTE RECURSO, YA ESTÁN COMPROMETIDOS 540 MILLONES. MAYO Y JUNIO: MESAS REMEN DE MINERÍA MUNICIPIO DE UBATÉ Y EN EL MUNICIPIO DE GUACHETÁ SE HACE ENTREGA DE BÁSCULAS DEL PROYECTO CENTRO MINERO. EN CUANTO AL CENTRO MINERO, ESTE SE ENCUENTRA TERMINANDO LA CONSTRUCCIÓN. SE ESTÁ TRABAJANDO EN ESTE MOMENTO EN LA JUSTIFICACIÓN TÉCNICA PARA REALIZAR AJUSTE AL PROYECTO DEL CENTRO MINERO - ENERGÉTICO DE CUNDINAMARCA, CON LA FINALIDAD DE ADICIONAR RECURSOS POR $1.300 MILLONES DE PESOS, QUE PERMITIRÁN FINANCIAR MAYORES CANTIDADES QUE SE HAN SUSCITADO CON EL AVANCE DE LA OBRA. A LA FECHA SE HA REALIZADO PAGO POR $ 993,068,283.00 DE $1,488,269,239.00. MARZO: LA ENTIDAD SE ENCUENTRA TERMINANDO LA CONSTRUCCIÓN DEL CENTRO MINERO ENERGÉTICO DE CUNDINAMARCA CON FECHA DE POSIBLE ENTREGA PARA EL 31 DE MAYO DE 2025. EN ESTE TÉRMINO SE ESTÁ ADELANTANDO GESTIONES CON EL SERVICIO NACIONAL DE APRENDIZAJE – SENA, PARA QUE ESTA SEA LA ENTIDAD QUE ASUME LA OPERACIÓN MANTENIMIENTO Y FUNCIONAMIENTO DEL CENTRO. HASTA EL MOMENTO EL SENA SE ENCUENTRA GESTIONANDO 2.200 MILLONES DE PESOS PARA LA DOTACIÓN DE GRAN PARTE DE LOS ESPACIOS DE AULAS Y LABORATORIOS. DE ESTE RECURSO, YA ESTÁN COMPROMETIDOS 540 MILLONES. AVANCE DEL 88.32% ABRIL: LA ENTIDAD CONTINÚA EN PROCESO DE TERMINACIÓN DE LA CONSTRUCCIÓN DEL CENTRO MINEROENERGÉTICO DE CUNDINAMARCA. MAYO: SE ESTÁ TRABAJANDO EN LA JUSTIFICACIÓN TÉCNICA PARA REALIZAR EL AJUSTE AL PROYECTO CON LA FINALIDAD DE ADICIONAR RECURSOS POR 1.300 MILLONES DE PESOS, QUE PERMITAN FINANCIAR MAYORES CANTIDADES QUE SE HAN SUSCITADO CON EL AVANCE DE LA OBRA.', NULL, NULL, NULL, NULL, NULL, 233, 'MINAS', 'COMPROMISO DEL GOBERNADOR - ESTRATÉGICO', 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.4080712&isFromPublicArea=True&isModal=False', NULL, NULL, 7370.00);
INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES ('CGNC957', 'UBATE', 'GUACHETA', 'TERMINACION DE LA CONSTRUCCION DEL CENTRO MINERO-ENERGETICO DE CUNDINAMARCA. DOTACION Y PUESTA EN MARCHA.', 'INFRAESTRUCTURA ENERGETICA', 'CENTRO MINERO-ENERGETICO', 'TERMINACION DE LA CONSTRUCCIION DEEL CENTRO MINERO-ENERGETITCO DE CUNDINAMARCA. DOTACION Y PUESTA EN MARCHA $ 16.655.165.706 * 15.300 MILLONES OFICIALES', NULL, 'AMPLIAR Y DOTAR EL CENTRO MINERO-ENERGÉTICO DE CUNDINAMARCA.', true, true, true, 'NO', 'MEDIA', 'EN CURSO', 16655165706.00, NULL, NULL, NULL, NULL, 'DEPARTAMENTO - SGR', 'SECRETARIA DE ENERGIAS Y MINERIA SOSTENIBLE', 'CONSORCIO CENTRO MINERO Y CONSORCIO SAKKOR', 'CONTRATO INTERADMINISTRATIVO', 'SMEG-LP-052-2022', 'CONSTRUCCIÓN DEL CENTRO MINERO - ENERGÉTICO DE CUNDINAMARCA', '15.300.851.909', 'Centro Minero', '2022-11-16', '2025-05-31', 'MARZO: LA ENTIDAD SE ENCUENTRA TERMINANDO LA CONSTRUCCIÓN DEL CENTRO MINERO ENERGÉTICO DE CUNDINAMARCA CON FECHA DE POSIBLE ENTREGA PARA EL 31 DE MAYO DE 2025. EN ESTE TÉRMINO SE ESTÁ ADELANTANDO GESTIONES CON EL SERVICIO NACIONAL DE APRENDIZAJE – SENA, PARA QUE ESTA SEA LA ENTIDAD QUE ASUME LA OPERACIÓN MANTENIMIENTO Y FUNCIONAMIENTO DEL CENTRO. HASTA EL MOMENTO EL SENA SE ENCUENTRA GESTIONANDO 2.200 MILLONES DE PESOS PARA LA DOTACIÓN DE GRAN PARTE DE LOS ESPACIOS DE AULAS Y LABORATORIOS. DE ESTE RECURSO, YA ESTÁN COMPROMETIDOS 540 MILLONES. AVANCE DEL 88.32% ABRIL:', NULL, false, NULL, NULL, 'Marzo: Inicia el trámite para realizar el ajuste al proyecto de regalías y posteriormente realizar los actos adminsitrativos correspondientes para adicionar los recursos propios del ajuste y prorroga en tiempo. El valor a adicionar será de 1.300 millones. ABRIL: La entidad se encuentra terminando la construcción del Centro Minero Energético de Cundinamarca con fecha de posible entrega para el 31 de mayo de 2025, a la fecha se cuenta con un avance aproximado del 64%. En este término se está adelantando gestiones con el Servicio Nacional de Aprendizaje – SENA, para que esta sea la entidad que asume la Operación Mantenimiento y Funcionamiento del centro. Hasta el momento el SENA se encuentra gestionando 2.200 millones de pesos para la dotación de gran parte de los espacios de aulas y laboratorios. De este recurso, ya están comprometidos 540 millones.', 234, 'MINAS', 'COMPROMISO DEL GOBERNADOR - ESTRATÉGICO', 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.2997599&isFromPublicArea=True&isModal=False', NULL, NULL, 7209.00);
INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES ('CGNC1238', 'UBATE', 'TAUSA', 'NO MENCIONA COMPROMISO
  ACOMPAÑAMIENTO REGULARIZACION MINERA Y TRAMITE PARA AUTORIZACIONES TEMPORALES', 'AMBIENTE', 'AUTORIZACION MINERA', 'NO MENCIONO COMPROMISO', NULL, 'PRESTAR ASISTENCIA TÉCNICA A 65 UNIDADES DE PRODUCCIÓN MINERA PARA EL CUMPLIMIENTO DE ESTÁNDARES DE SEGURIDAD Y SOSTENIBILIDAD AMBIENTAL.', true, NULL, false, 'NO', 'MEDIA', 'EN CURSO', NULL, NULL, NULL, NULL, NULL, 'DEPARTAMENTO', 'SECRETARIA DE ENERGIAS Y MINERIA SOSTENIBLE', 'ANM Y CAR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'MARZO: EL MARTES 8 DE ABRIL SE TIENE PROYECTADA UNA REUNION CON LA ALCALDIA PARA DEFINIR EL ALCANCE DEL APOYO QUE SE VA A DAR EN EL MARCO DE LOS COMPROMISOS DEL GOBERNADOR. MAYO: SE REALIZA REUNIÓN CON LA CAR PARA ABORDAR LA PROBLEMÁTICA SOBRE DETERMINANTES AMBIENTALES EN EL MUNICIPIO DE TAUSA, TEMA FUNDAMENTAL PARA GARANTIZAR LA INCLUSIÓN DE LA DIMENSION AMBIENTAL Y LA ARMONIZACIÓN DE LOS INSTRUMENTOS DE PLANIFICACIÓN. MARZO: MEDIANTE LA REUNIÓN SE DEFINIRÁ LAS NECESIDADES DEL MUNICIPIO LAS CUALES AL MOMENTO NO SON CLARAS. ABRIL Y MAYO: SE REALIZÓ UNA REUNIÓN CON LA CAR PARA ABORDAR PROBLEMÁTICA SOBRE DETERMINANTES AMBIENTALES EN EL MUNICIPIO DE TAUSA, TEMA FUNDAMENTAL PARA GARANTIZAR LA INCLUSIÓN DE LA DIMENSIÓN AMBIENTAL Y LA ARMONIZACIÓN DE LOS INSTRUMENTOS DE PLANIFICACIÓN, A FIN DE INCIDIR EN LAS DINÁMICAS PROPIAS DEL MUNICIPIO', NULL, NULL, NULL, NULL, NULL, 235, 'MINAS', 'COMPROMISO DEL GOBERNADOR - ESTRATÉGICO', NULL, NULL, NULL, NULL);
INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES (NULL, 'UBATE', 'LENGUAZAQUE', 'REVISAR COMPROMISO CON DESPACHO', 'AMBIENTE', 'AUTORIZACION MINERA', 'ASISTENCIA TECNICA Y ACOMPAÑAMIENTO PARA TRAMITE DE AUTORIZACION TEMPORAL MINERA. SIN DEFINIR PRESUPUESTO.', NULL, 'PRESTAR ASISTENCIA TÉCNICA A 65 UNIDADES DE PRODUCCIÓN MINERA PARA EL CUMPLIMIENTO DE ESTÁNDARES DE SEGURIDAD Y SOSTENIBILIDAD AMBIENTAL.', true, NULL, false, 'NO', 'MEDIA', 'EN CURSO', NULL, NULL, NULL, NULL, NULL, 'DEPARTAMENTO - MUNICIPIO', 'SECRETARIA DE ENERGIAS Y MINERIA SOSTENIBLE', 'AGENCIA NACIONAL DE MINERIA', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'MARZO: A LA FECHA SE ESTÁ PRESTANDO EL ACOMPAÑAMIENTO A UN CONTRATO ESPECIAL DE CONCESIÓN MINERA DEL MUNICIPIO PARA APOYARLO EN SU PROCESO DEL TRÁMITE AMBIENTAL.
  
  SE HA CONTACTADO A LOS BENEFICIARIOS DEL ARE, Y SE REALIZÓ REUNIÓN EL DÍA 20 DE MARZO DE 2025 DE ACERCAMIENTO CON EL ARE Y ESTABLECIMIENTO DE ACTIVIDADES EN EL MARCO DE LA GESTION QUE REALIZA LA SEMS.
  
  EL 1 DE ABRIL SE REALIZÓ REUNIÓN CON LA CAR PARA EXPONER PROBLEMATICA RELACIONADA CON EL LICENCIAMIENTO AMBIENTAL PARA EL CUAL SE PROPONE REALIZAR MESAS DE TRABAJO CON EL AREA JURIDICA DE LA CORPORACIÓN. ABRIL Y MAYO: A LA FECHA SE ESTÁ PRESTANDO EL ACOMPAÑAMIENTO AL CONTRATO ESPECIAL DE CONCESIÓN MINERA DEL MUNICIPIO DE LENGUAZAQUE PARA APOYARLO EN SU PROCESO DEL TRÁMITE AMBIENTAL. MARZO: ELABORACIÓN DE PLAN DE TRABAJO ENTRE ENTIDADES Y BENEFICIARIOS. ABRIL Y MAYO: ABRIL Y MAYO: A LA FECHA SE ESTÁ PRESTANDO EL ACOMPAÑAMIENTO AL CONTRATO ESPECIAL DE CONCESIÓN MINERA DEL MUNICIPIO DE LENGUAZAQUE PARA APOYARLO EN SU PROCESO DEL TRÁMITE AMBIENTAL.', NULL, NULL, NULL, NULL, '1 de abril 2025 se realizo asistencia tecnica al titulo minero ED1-073 en la mina UPM la Nacional de Carbones en el componente minero, ambiental, social, seguridad y salud en el trabajo. Segunda visita de seguimiento el 19 de agosto para revisar el cumplimiento de la primera visita.', 236, 'MINAS', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES ('CGNC871', 'SUMAPAZ', 'ARBELAEZ', 'ACOMPAÑAMIENTO REGULARIZACION MINERA Y TRAMITE PARA AUTORIZACIONES TEMPORALES', 'AMBIENTE', 'AUTORIZACION MINERA', 'ACOMPAÑAMIENTO REGULARIZACION MINERA Y TRAMITE PARA AUTORIZACIONES TEMPORALES. SIN DEFINIR PRESUPUESTO', NULL, 'PRESTAR ASISTENCIA TÉCNICA A 65 UNIDADES DE PRODUCCIÓN MINERA PARA EL CUMPLIMIENTO DE ESTÁNDARES DE SEGURIDAD Y SOSTENIBILIDAD AMBIENTAL.', true, true, false, 'NO', 'MEDIA', 'EN CURSO', NULL, NULL, NULL, NULL, NULL, 'DEPARTAMENTO', 'SECRETARIA DE BIENESTAR VERDE - SECRETARIA DE MINAS- ICCU', NULL, NULL, NULL, NULL, NULL, 'Asistencia Técnica', '2025-02-03', '2025-10-02', 'MARZO: REUNIONES CON EL ALCALDE MUNICIPAL EL DÍA 19 DE MARZO PARA EXPLICAR QUE EXISTE UN REQUERIMIENTO REALIZADO POR LA ANM RESPECTO AL TRAMITE DE AUTORIZACIÓN TEMPORAL QUE SE ENCUENTRA ADELANTANDO.', 'Orientación por parte de los contratistas de la SEMS a la alcaldia municipal para dar respuesta a los requerimientos establecidos por la ANM.
  Orientación en la realización del PTE y licencia ambiental de la Autorización Temporal.
  Por parte de la alcaldia deben realizar la consulta ante la CAR sobre el sancionatorio y dispone del equipo tecnico para la orientación en el proceso de atencion de requerimientos ante las autoridades (ANM-CAR).
  Confirmar el presupuesto con el que cuenta el municipio para el desarrollo de los documentos tecnicos.', false, NULL, NULL, 'Marzo: No se cuenta con presupuesto para realizar estudios propios de una consultoría para los documentos entregables que los municipios deben realizar como el PTE y la licencia ambiental. Sin embargo, se cuenta con dos Contrato de Prestación de Servicios SEMS-CPS-012-2025 y SEMS-CPS-004-2025 para realizar el respectivo acompañamiento a los municipios para asesorar frente a las trámites ante las respectivas autoridades. ABRIL: El día 7 de abril se realizó la segunda Mesa Integrada para la prevención de accidentalidad minera en el altiplano Cundiboyacense, conformada por distintas entidades como lo es Ministerio de Minas y Energía, Agencia Nacional de Minería, CAR, SENA, Gobernación de Cundinamarca a través de la Secretaría de Energías y Minería Sostenible y Unidades Especial de Gestión del Riesgo y representantes del gremio minero. Esta mesa busca articular un plan de trabajo entre los actores mencionados para disminuir la accidentalidad y trabajar en procesos de formalización minera.', 237, 'MINAS', 'COMPROMISO DEL GOBERNADOR - ESTRATÉGICO', NULL, NULL, NULL, NULL);
INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES ('CGNC852', 'TEQUENDAMA', 'ANOLAIMA', 'ASISTENCIA TECNICA Y ACOMPAÑAMIENTO PARA TRAMITE DE AUTORIZACION TEMPORAL', 'AMBIENTE', 'AUTORIZACION MINERA', 'ASISTENCIA TECNICA Y ACOMPAÑAMIENTO PARA TRAMITE DE AUTORIZACION TEMPORAL. SIN DEFINIR PRESUPUESTO', NULL, 'PRESTAR ASISTENCIA TÉCNICA A 65 UNIDADES DE PRODUCCIÓN MINERA PARA EL CUMPLIMIENTO DE ESTÁNDARES DE SEGURIDAD Y SOSTENIBILIDAD AMBIENTAL.', true, true, false, 'NO', 'MEDIA', 'EN CURSO', NULL, NULL, NULL, NULL, NULL, 'DEPARTAMENTO', 'SECRETARIA DE BIENESTAR VERDE - SECRETARIA DE MINAS- ICCU', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'MARZO: SE REMITIÓ VIA CORREO ELECTRÓNICO EL OFRECIMIENTO A LA ALCALDIA DEL APOYO DE ASISTENCIA TECNICA POR PARTE DE LA SECRETARÍA PERO NO HA HABIDO RESPUESTA POR PARTE DEL MUNICIPIO.MARZO: NO SE CUENTA CON PRESUPUESTO PARA REALIZAR ESTUDIOS PROPIOS DE UNA CONSULTORÍA PARA LOS DOCUMENTOS ENTREGABLES QUE LOS MUNICIPIOS DEBEN REALIZAR COMO EL PTE Y LA LICENCIA AMBIENTAL. SIN EMBARGO, SE CUENTA CON DOS CONTRATO DE PRESTACIÓN DE SERVICIOS SEMS-CPS-012-2025 Y SEMS-CPS-004-2025 PARA REALIZAR EL RESPECTIVO ACOMPAÑAMIENTO A LOS MUNICIPIOS PARA ASESORAR Y ORIENTAR FRENTE A LAS TRÁMITES ANTE LAS RESPECTIVAS AUTORIDADES. ABRIL: EL DÍA 7 DE ABRIL SE REALIZÓ LA SEGUNDA MESA INTEGRADA PARA LA PREVENCIÓN DE ACCIDENTALIDAD MINERA EN EL ALTIPLANO CUNDIBOYACENSE, CONFORMADA POR DISTINTAS ENTIDADES COMO LO ES MINISTERIO DE MINAS Y ENERGÍA, AGENCIA NACIONAL DE MINERÍA, CAR, SENA, GOBERNACIÓN DE CUNDINAMARCA A TRAVÉS DE LA SECRETARÍA DE ENERGÍAS Y MINERÍA SOSTENIBLE Y UNIDADES ESPECIAL DE GESTIÓN DEL RIESGO Y REPRESENTANTES DEL GREMIO MINERO. ESTA MESA BUSCA ARTICULAR UN PLAN DE TRABAJO ENTRE LOS ACTORES MENCIONADOS PARA DISMINUIR LA ACCIDENTALIDAD Y TRABAJAR EN PROCESOS DE FORMALIZACIÓN MINERA. MAYO: SIN NOVEDADES', NULL, NULL, NULL, NULL, NULL, 238, 'MINAS', 'COMPROMISO DEL GOBERNADOR - ESTRATÉGICO', NULL, NULL, NULL, NULL);
