INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES ('CGNC10', 'MAGDALENA CENTRO', 'BELTRAN', 'COMPRA DE BUS PARA USO DE LA POBLACIÓN BENEFICIARIA DE PROGRAMAS SOCIALES', 'VEHÍCULO', 'BUS', 'ENTREGA DE BUS PARA EL MUNICIPIO, CON EL FIN DE BENEFICIAR A LOS CIUDADANOS BENEFICIARIOS DE LOS PROGRAMAS SOCIALES', '79.0', 'Implementar 1 programa de transporte que facilite e incremente la asistencia de la población rural dispersa a los programas sociales municipales.', NULL, false, false, 'NO', 'MEDIA', 'NO SE HA INICIADO', 85000000000.00, 850000000.00, 0.00, 0.00, NULL, 'DEPARTAMENTO', 'SECRETARIA DE LO SOCIAL Y LA FAMILIA', NULL, 'CONTRATO DE SUMINISTRO', NULL, NULL, NULL, NULL, '2026-03-04', '2026-10-10', 'LA SECRETARIA IDENTIFICO, JUNTO CON LOS MUNICIPIOS, LAS NECESIDADES PARA LA IMPLEMENTACION DE LOS PROGRAMAS SOCIALES Y SE ESTABLECIO EL COMPROMISO CORRESPONDIENTE CON EL DESPACHO.
SE HAN ADELANTADO LOS PROCESOS DE COTIZACIÓN Y LA CONSTRUCCIÓN DE LA FICHA TECNICA.
ASIMISMO, SE ARTICULARON ESFUERZOS CON LA OFICINA DE PRENSA PARA EL DISEÑO DE LAS PIEZAS COMUNICACIONALES, LAS CUALES YA CUENTAN CON SU APROBACION.', 'SE REQUIERE LA PRIORIZACION DE MUNICIPIOS POR PARTE DEL DESPACHO, CON EL FIN DE DETERMINAR Y PROGRAMAR LA INVERSIÓN PARA LAS PROXIMAS VIGENCIAS.', NULL, 'EL PROCESO DE CONTRATACION DEPENDE DE LA ASIGNACION DE RECURSOS PARA LA ADQUISICION DEL VEHICULO. LOS RECURSOS ESTAN SUPEDIDATOS A QUE SE ASIGNEN EN EL RUBRO Y SE PRIORICEN LOS MUNICIPIOS EN LOS DOS AÑOS SUBSIGUIENTES, SEGUN INDICACION DE DESPACHO.', NULL, 'NINGUNA', 2988, 'SOCIAL Y FAMILIA', 'COMPROMISO DEL GOBERNADOR - OFERTA INSTITUCIONAL', NULL, NULL, 0.00, 0.00);
