INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES ('COI352', 'TEQUENDAMA', 'EL COLEGIO', 'ESTUDIO DE TRAFICO', 'TRANSPORTE', 'SEÑALIZACION VIAL', 'ESTUDIO SOBRE EL TRAFICO SOBRE LA VELOCIDADES QUE TIENE QUE TENER EL CORREDOR EL ALCALDE HA HECHO UNA SOLICITUD DE PODER HACER UNOS REDUCTORES DE VELOCIDAD EN ALGUNOS PUNTOS DEL CORREDOR SE REVISARA CON LAS VELOCIDADES MINIMAS SI ESTO ES POSIBLE ESPERAR A LOS RESULTADOS DEL ESTUDIO', '190', 'IMPLEMENTAR MEDIDAS DE SEGURIDAD VIAL EN PUNTOS CRITICOS DE SINIESTRALIDAD | INTERVENIR 80 PUNTOS EN INFRAESTRUCTURA PARA MEJORAR LAS CONDICIONES DE SEGURIDAD VIAL DEL DEPARTAMENTO.', true, true, true, 'ATENDER UN PUNTO CRITICO DE SEÑALIZACION VIAL EN EL MUNICIPIO', 'MEDIA', 'COMPLETADO', 144626372.00, 144626372.00, NULL, NULL, NULL, 'DEPARTAMENTO', 'SECRETARIA DE MOVILIDAD CONTEMPORANEA', 'MUNICIPIO DEL COLEGIO', 'CONTRATO DE OBRA', 'STM LP 374 2023
  STM LP 008 2025', 'IMPLEMENTAR INTERVENCIONES EN INFRAESTRUCTURA VIAL PARA MEJORAR LAS CONDICIONES DE SEGURIDAD VIAL Y MITIGAR RIESGOS EN PUNTOS CRITICOS PRIORIZADOS A CARGO DEL DEPARTAMENTO DE CUNDINAMARCA', '$ 3.480.023.139', 'PUNTOS INTERVENIDOS', NULL, NULL, 'SE REALIZO UNA VISITA AL MUNICIPIO PARA LA PRIORIZACION Y SELECCION DE PUNTOS. SE DEFINIERON TRES PUNTOS DE INTERVENCION CON EL ALCALDE. 
  LA SMC ELABORO LAS PROPUESTAS ESQUEMATICAS DE MEDIDAS DE SEGURIDAD VIAL PARA LOS TRES PUNTOS CRITICOS Y LOS ENTREGO A LOS CONTRATISTAS DE OBRA E INTERVENTORIA.
  EL CONTRATISTA JUNTO CON LA INTERVENTORIA Y SMC REALIZO LA VISITA DE RECONOCIMIENTO A LOS TRES PUNTOS A FINALES DEL MES DE JUNIO.
  EL CONTRATISA RADICO ANTE EL MUNICIPIO DE EL COLEGIO LA SOLICITUD DE APROBACION DE LOS PLANES DE MANEJO DE TRANSITO PMTS Y EL MUNICIPIO EMITIO APROBACION EL 04 DE AGOSTO. 
  LA INTERVENTORIA APROBO LOS INFORMES DE VISITA DE RECONOCIMIENTO Y SE SUSCRIBIERON LAS ACTAS DE APROPIACION DE DISEÑOS PARA LOS TRES PUNTOS PRIORIZADOS EL 06 Y 10 DE AGOSTO.
  SE INICIO LA IMPLEMENTACION DE LOS PUNTOS EL 09 DE AGOSTO Y SE REALIZO LA VISITA DE RECIBO POR PARTE DE LA SMC EL 17/09/2025', 'COBRO Y PAGO DE LOS 3 PUNTOS IMPLEMENTADOS EN 2025', NULL, 'NO APLICA', NULL, 'EN 2025 SE IMPLEMENTARON MEDIDAS DE SEGURIDAD VIAL EN 3 PUNTOS PRIORIZADOS POR EL MUNICIPIO:
  + 25245_CN_01: CRA 4 CL 6 Y 7. VALOR EJECUTADO $41.342.586
  + 25245_CN_02: CARRERA 8 ENTRE CL 9 Y CL 5. VALOR EJECUTADO $61.262.176
  + 25245_CN_03: CALLE 8 ENTRE CL 9 Y VIA 40CN03. VALOR EJECUTADO $42.021.610
  LA INVERSION TOTAL FUE DE $144.626.372
  
  LAS MEDIDAS DISEÑADAS INCLUYEN INSTALACION DE SEÑALES VERTICALES DEMARCACION HORIZONTAL Y MEDIDAS PARA GESTIONAR LA VELOCIDAD QUE INCLUYEN EL REEMPLAZO Y DEMOLICION DE RESALTOS PARABOLICOS Y PINTURA DE BANDAS ALERTADORAS.', 3285, 'MOVILIDAD', 'COMPROMISO DEL GOBERNADOR OFERTA INSTITUCIONAL', 'HTTPS://COMMUNITY.SECOP.GOV.CO/PUBLIC/TENDERING/OPPORTUNITYDETAIL/INDEX?NOTICEUID=CO1.NTC.7052705&ISFROMPUBLICAREA=TRUE&ISMODAL=TRUE&ASPOPUPVIEW=TRUE', NULL, 1.00, 10.00);
