INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES (NULL, 'MEDINA', 'PARATEBUENO', 'Revision predios de la SAE', 'CATASTRO', 'Catastro', 'EN EL MUNICIPIO DE PARATEBUENO SE ADELANTÓ LA PRIORIZACIÓN E INTERVENCIÓN DE PREDIOS DE INTERÉS DE LA SOCIEDAD DE ACTIVOS ESPECIALES (SAE), EL EQUIPO DE CATASTRO Y LA AGENCIA DE COORDINACIÓN Y CONTROL (ACC). EL PROPÓSITO DE ESTA INTERVENCIÓN FUE IDENTIFICAR, VERIFICAR Y DEFINIR LOS PREDIOS BAJO ADMINISTRACIÓN DE LA SAE QUE PUEDAN SER DESTINADOS A PROCESOS DE REUBICACIÓN DE LAS FAMILIAS DE LA VEREDA LA EUROPA, PRIORIZANDO AQUELLOS CON CONDICIONES JURÍDICAS Y TÉCNICAS APTAS PARA USO.
LA ACC ACOMPAÑO LA GESTIÓN INTERINSTITUCIONAL, ASEGURANDO LA ARTICULACIÓN ENTRE EL MUNICIPIO, LA SAE Y LAS ENTIDADES DEL ORDEN DEPARTAMENTAL, PARA GARANTIZAR QUE LA DISPOSICIÓN DE LOS PREDIOS SE REALICE CONFORME A LOS LINEAMIENTOS LEGALES Y AL PLAN DE DESARROLLO DEPARTAMENTAL (PDD). ESTA ACCIÓN CONTRIBUIRÁ DIRECTAMENTE AL CUMPLIMIENTO DEL OBJETIVO DE BRINDAR SOLUCIONES HABITACIONALES SEGURAS Y SOSTENIBLES A LAS FAMILIAS EN CONDICIÓN DE VULNERABILIDAD, PROMOVIENDO EL USO EFICIENTE DEL SUELO Y LA REGULARIZACIÓN TERRITORIAL', 'NO APLICA', 'CON MOTIVO DEL TERREMOTO DE PARATEBUENO Y MEDINA, LA AGENCIA CATASTRAL DE CUNDINAMARCA REALIZÓ EL LEVANTAMIENTO DE INFORMACIÓN FÍSICA Y JURÍDICA (CON APOYO DE SECRETARIA DE VIVIENDA) DE LOS PREDIOS AFECTADOS POR EL EVENTO. | LEVANTAMIENTO 445', true, false, false, 'NO', 'MEDIA', 'FINALIZADO', NULL, NULL, NULL, NULL, NULL, 'NO APLICA', 'SECRETARIA DE VIVIENDA - AGENCIA CATASTRAL DE CUNDINAMARCA', 'SAE', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SE REALIZÓ RECORRIDO A LOS PREDIOS DE LA SAE EN EL SECTOR DE MAYA, CON EL FIN DE VERIFICAR CARACTERÍSTICAS Y POSIBLES USOS DE LOS PREDIOS.', 'NINGUNA', NULL, NULL, NULL, NULL, 3468, 'CATASTRO', 'COMPROMISO DEL GOBERNADOR - ESTRATEGICO', NULL, 'SI', NULL, NULL);
