INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES (NULL, 'TODAS LAS PROVINCIAS', 'TODOS LOS MUNICIPIOS', 'ENTREGAR SUBSIDIOS EDUCATIVOS PARA EXALTAR EL DESEMPEÑO ACADEMICO Y CONTRIBUIR AL PROCESO DE FORMACION INTEGRAL DE LOS HIJOS DE LOS AFILIADOS, SELECCIONANDO A AQUELLOS QUE OBTENGAN LOS MEJORES RESULTADOS EN LAS PRUEBAS SABER 11 - ICFES Y A LOS DE MEJORES PROMEDIOS EN EDUCACION SUPERIOR, PARA QUE CONTINUEN CON SUS ESTUDIOS.', 'BIENESTAR AFILIADOS', 'SUBSIDIOS EDUCATIVOS', 'POR MEDIO DE UNA CONVOCATORIA, SE SELECCIONA A LOS MEJORES ESTUDIANTES PARA ENTREGARLES UN SALARIO MINIMO LEGAL VIGENTE PARA EL PAGO DE MATRICULA DE EDUCACION SUPERIOR, EN PROGRAMAS ACADEMICOS DE NIVEL (TECNICO, TECNOLOGICO O PROFESIONAL), ASI COMO PARA ADELANTAR ESTUDIOS DE CARRERA MILITAR O DE POLICIA, SIN  QUE  EL  MONTO DEL SUBSIDIO OTORGADO SUPERE EL 100% DE LOS COSTOS DE LA MISMA. DIRIGIDA A LOS HIJOS DE LOS AFILIADOS, PARA QUE PUEDAN ADELANTAR ESTUDIOS SUPERIORES, PREVIO CUMPLIMIENTO DE LOS REQUISITOS ESTABLECIDOS EN LA NORMATIVIDAD VIGENTE.

DURANTE EL 2024, SE ENTREGARON 66 SUBSIDIOS EDUCATIVOS BENEFICIANDO A LOS HIJOS DE LOS AFILIADOS DE LA CORPORACION SOCIAL DE CUNDINAMARCA. 

DURANTE LA VIGENCIA DEL 2025 SE HAN ENTREGADO 53 SUBSIDIOS EDUCATIVOS BENEFICIANDO A LOS HIJOS DE LOS AFILIADOS DE LA CORPORACION SOCIAL DE CUNDINAMARCA.', NULL, 'SUBSIDIOS EDUCATIVOS', NULL, NULL, NULL, NULL, 'ALTA', 'EN CURSO', 127968312.00, NULL, NULL, NULL, NULL, NULL, 'CORPORACION SOCIAL DE CUNDINAMARCA - CSC', 'NINGUNA', NULL, NULL, NULL, NULL, 'GIRO A CADA AFILIADO BENEFICIADO POR CONCEPTO DE SUBSIDIO EDUCATIVO PARA SU HIJO POR VALOR DE UN SALARIO MINIMO LEGAL VIGENTE POR CADA SEMESTRE Y HASTA LA FINALIZACION DE LA CARRERA, SIEMPRE Y CUANDO SE CUMPLA CON TODOS LOS REQUISITOS DE LA NORMATIVA VIGENTE', NULL, NULL, 'LANZAMIENTO DE LA CONVOCATORIA POR CADA ANUALIDAD, ES DECIR UNA EN EL 2024 Y OTRA EN EL 2025, CUMPLIMIENTO DE CADA UNA DE LAS ETAPAS COMO SON PUBLICACION, INSCRIPCIONES, RECEPCION Y VERIFICACION DE DOCUMENTOS Y REQUISITOS, RESPUESTA A RECLAMACIONES, CREACION DE TERCEROS EN EL SISTEMA NOVASOFT Y EJECUTAR TODO EL PROCEDIMIENTO ESTABLECIDO PARA EL RECONOCIMIENTO Y PAGO DE LOS SUBSIDIOS EDUCATIVOS', 'LA CONVOCATORIA SE RIGE POR EL ACUERDO 009 DEL 9 DE SEPTIEMBRE DEL 2021 Y ANUALMENTE SE EXPIDE UNA RESOLUCION CON CRONOGRAMA PARA LA CONVOCATORIA.
LA CONVOCATORIA DEL 2024 SE DESARROLLO CONFORME AL CRONOGRAMA Y DURANTE EL 2025 SE ESTA ADELANTANDO CON CUMPLIMIENTO DEL CRONOGRAMA QUE FINALIZA EN NOVIEMBRE CON LA ACEPTACION DEL SUBSIDIO POR PARTE DE LOS NUEVOS BENEFICIADOS QUIENES ADJUNTAN LOS DOCUMENTOS NECESARIOS PARA EL TRAMITE DE GIRO.', NULL, NULL, NULL, 'ANUALMENTE SEGUN  NORMATIVA VIGENTE, SE OFRECEN 44 SUBSIDIOS EDUCATIVOS PARA ESTUDIOS SUPERIORES DE LOS HIJOS DE LOS AFILIADOS,  PREVIO CUMPLIMIENTO DE LOS REQUISITOS ESTABLECIDOS 

DURANTE LA VIGENCIA DEL 2024 SE RECIBIERON 38 POSTULACIONES DE LAS CUALES 30 CUMPLIERON CON LOS REQUISITOS Y SUMANDO A ESTOS, LOS 20 BENEFICIARIOS QUE VENIAN DESDE CONVOCATORIAS ANTERIORES, SE COMPLETARON 50 BENEFICIARIOS DE LOS SUBSIDIOS EDUCATIVOS EN EL 2024, VIGENCIA EN LA QUE SE REALIZARON 66 GIROS POR CONCEPTO DE SUBSIDIO EDUCATIVOS.

EN LA VIGENCIA ACTUAL, LA CONVOCATORIA ESTA EN DESARROLLO Y SE RECIBIERON 33 NUEVAS POSTULACIONES QUE YA PASARON POR VERIFICACION DE REQUISITOS.  LA RESOLUCION DE ADJUDICACION SERA PUBLICADA EL 5 DE NOVIEMBRE UNA VEZ SE REVISE NUEVAMENTE PUES ALGUNOS ENVIARON DOCUMENTOS PARA SUBSANAR. 
DURANTE EL 2025 Y A LA FECHA SE HAN EFECTUADO 53 GIROS POR CONCEPTO DE SUBSIDIO EDUCATIVOS.', 3528, 'CORPORACION SOCIAL', 'GESTION NO INCORPORADA', NULL, NULL, 7.00, 666.00);
INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES (NULL, 'TODAS LAS PROVINCIAS', 'TODOS LOS MUNICIPIOS', 'FORTALECER LAS COMPETENCIAS ACADEMICAS, FUNCIONALES Y COMPORTAMENTALES DE LOS AFILIADOS A LA CORPORACION SOCIAL DE CUNDINAMARCA Y DE SU NUCLEO FAMILIAR, QUE SE VEAN REFLEJADAS EN SU DESEMPEÑO LABORAL Y ESTILO DE VIDA.', 'BIENESTAR AFILIADOS', 'CAPACITACIONES', 'DURANTE LA VIGENCIA 2024 SE REALIZARON CUATRO (4) CURSOS, QUE SE IDENTIFICARON A TRAVES DE LA ENCUESTA DE NECESIDADES APLICADAS A UNA MUESTRA DEL 30% DE LOS AFILIADOS, EN TEMAS COMO: EMPRENDIMIENTO EMPRESARIAL, COMUNICACION ASERTIVA, MANEJO DE LA EMOCIONES Y LIDERAZGO; REDACCION Y ORTOGRAFIA, GESTION DEL RIESGO Y MANEJO DE EMERGENCIAS, DIRIGIDOS A LOS AFILIADOS Y A SUS BENEFICIARIOS, DONDE SE LOGRO LA INSCRIPCION DE 248 PERSONAS.

A PARTIR DEL MES DE OCTUBRE DE 2024, SE IDENTIFICO LA NECESIDAD DE OFERTAR CONFERENCIAS VIRTUALES, CON EL PROPOSITO DE ALCANZAR EL MAYOR NUMERO DE PARTICIPANTES Y MAYOR ACCESIBILIDAD PARA LAS 15 PROVINCIAS DEL DEPARTAMENTO, POR LO QUE EN EL MES DE OCTUBRE SE ABRIO CONVOCATORIA PARA INSCRIPCION DE LA PRIMERA CONFERENCIA VIRTUAL MAS QUE PALABRAS: COMUNICACION EFECTIVA PARA RESOLVER CONFLICTOS Y CONSTRUIR RELACIONES CON UNA ASISTENCIA DE 19 PERSONAS, EN DOS HORARIOS DIFERENTES.  DURANTE EL MES DE NOVIEMBRE SE ABRE CONVOCATORIA PARA EL MISMO TEMA DE CONFERENCIA, CON UNA ASISTENCIA DE 9 PERSONAS EN DOS HORARIOS DIFERENTES Y DURANTE EL MES DE DICIEMBRE SE ABRE CONVOCATORIA PARA INSCRIPCION DE LA CONFERENCIA VIRTUAL PRIMEROS AUXILIOS PSICOLOGICOS CON UNA ASISTENCIA DE 9 PERSONAS, EN DOS HORARIOS DIFERENTES, PARA UN TOTAL DE 6 CONFERENCIAS DICTADAS EN 2024, CON UNA ASISTENCIA DE 37 PERSONAS. 

EN LA ACTUALIDAD, SE ENCUENTRAN EN DESARROLLO 3 DIPLOMADOS Y 4 CURSOS DE CAPACITACION PARA 464 INSCRITOS, ENTRE AFILIADOS Y BENEFICIARIOS.  LOS DIPLOMADOS SON: DIPLOMADO EN INTELIGENCIA ARTIFICIAL, DIPLOMADO EN HERRAMIENTAS OFIMATICAS, DIPLOMADO EN EMPRENDIMIENTO Y GESTION EMPRESARIAL.  LOS CURSOS SON: CURSO DE DECORACION NAVIDEÑA, CURSO DE REDACCION DE TEXTOS INSTITUCIONALES Y ORTOGRAFIA, CURSO COCINANDO SUEÑOS E ILUSIONES, CURSO DE MANEJO DE IMAGEN PERSONAL Y MAQUILLAJE.

DURANTE EL 2025, SE HAN DICTADO LAS SIGUIENTES CONFERENCIAS VIRTUALES: EN FEBRERO, CONFERENCIA VIRTUAL MAS QUE PALABRAS: COMUNICACION EFECTIVA PARA RESOLVER CONFLICTOS Y CONSTRUIR RELACIONES CON UNA ASISTENCIA DE 59 PERSONAS, EN DOS FECHAS DIFERENTES.  EN EL MISMO MES, CONFERENCIA VIRTUAL PRIMEROS AUXILIOS PSICOLOGICOS CON UNA ASISTENCIA DE 27 PERSONAS, EN DOS FECHAS DIFERENTES.  EN MARZO, CONFERENCIA VIRTUAL MANEJO DEL ESTRES Y LA ANSIEDAD CON UNA ASISTENCIA DE 8 PERSONAS, EN UNA SOLA FECHA.  EN ABRIL CONFERENCIA VIRTUAL MANEJO DEL ESTRES Y LA ANSIEDAD CON UNA ASISTENCIA DE 23 PERSONAS, EN DOS FECHAS DIFERENTES. EN MAYO, CONFERENCIA VIRTUAL HABLEMOS DE TRISTEZA Y DEPRESION CON UNA ASISTENCIA DE 46 PERSONAS, EN TRES FECHAS DIFERENTES. EN JUNIO, CONFERENCIA VIRTUAL LA MAGIA DEL DESACUERDO: TRANSFORMA CONFLICTOS EN OPORTUNIDADES CON UNA ASISTENCIA DE 14 PERSONAS, EN UNA SOLA FECHA. EN JULIO, CONFERENCIA VIRTUAL LA MAGIA DEL DESACUERDO: TRANSFORMA CONFLICTOS EN OPORTUNIDADES CON UNA ASISTENCIA DE 51 PERSONAS, EN DOS FECHAS DIFERENTES; EN AGOSTO, CONFERENCIA VIRTUAL APRENDE A COMBATIR LA PROCASTINACION: TU, YO DEL FUTURO LO AGRADECERA CON UNA ASISTENCIA DE 29 PERSONAS, EN DOS FECHAS DIFERENTES. EN SEPTIEMBRE, CONFERENCIA VIRTUAL EL CORAZON DEL DINERO: COMO LAS EMOCIONES MANEJAN SUS FINANZAS CON UNA ASISTENCIA DE 27 PERSONAS, EN DOS FECHAS DIFERENTES. PARA UN TOTAL DE 265 PERSONAS ENTRE AFILIADOS Y BENEFICIARIOS, QUE SE FAVORECIERON CON LAS CAPACITACIONES Y UN TOTAL DE 16 CONFERENCIAS DICTADAS DURANTE EL 2025.', NULL, 'CAPACITACIONES', NULL, NULL, NULL, NULL, 'ALTA', 'EN CURSO', 3419563097.00, NULL, NULL, NULL, NULL, NULL, 'FONDECUN EN EL 2024





UNIVERSIDAD DE CUNDINAMARCA EN EL 2025', 'FONDECUN (2024)





UNIVERSIDAD DE CUNDINAMARCA (2025)', 'CONTRATO INTERADMINISTRATIVO', NULL, 'FONDECUN: GERENCIA INTEGRAL PARA EL DESARROLLO DE LA PLANIFICACION OPERACION DEL PROYECTO PARA LA SELECCION DE INCENTIVOS, PIEZAS PROMOCIONALES Y CAPACITACIONES PARA LOS AFILIADOS DE LA CSC Y SUS BENEFICIARIOS, EN EL MARCO DEL CONVENIO No 24-059 DE 2024 SUSCRITO CON FONDECUN, CON EL FIN DE LOGRAR LA FIDELIZACION Y CAPACITACION DE NUEVOS AFILIADOS A LA ENTIDAD GENERANDO UN IMPACTO SOCIAL EN LA COMUNIDAD.

UNIVERSIDAD DE CUNDINAMARCA:DESARROLLO DE ACTIVIDADES TENDIENTES A LA EJECUCION DEL PLAN INSTITUCIONAL DE CAPACITACION PARA LOS FUNCIONARIOS Y EL PROGRAMA DE CAPACITACION PARA AFILIADOS DE LA CORPORACION SOCIAL DE CUNDINAMARCA Y SUS BENEFICIARIOS PARA LA VIGENCIA 2025', NULL, 'CURSOS DE CAPACITACION CERTIFICADOS  2024






CURSOS Y DIPLOMADOS CERTIFICADOS  2025', NULL, NULL, 'DURANTE EL 2024 SE EFECTUO UNA ENCUESTA DE NECESIDADES DE LOS AFILIADOS, ADELANTADA DURANTE EL SEGUNDO TRIMESTRE  POR MEDIO DE UN FORMULARIO VIRTUAL ENVIADO A TODOS LOS AFILIADOS PARA ELABORAR UN DIAGNOSTICO DE NECESIDADES DE ACUERDO A LOS INTERESES Y EXPECTATIVAS QUE MANIFESTARON EN LAS RESPUESTAS DEL CUESTIONARIO Y TOMARLO COMO INSUMO PARA LAS PROPUESTA DEL PROGRAMA DE CAPACITACION.
SE ADELANTARON ESTUDIOS PREVIOS Y PROCESO DE CONTATACION Y SE REALIZARON LAS CAPACITACIONES CON FONDECUN, EFECTUANDO LAS PREINSCRIPCIONES EN LA CORPORACION  Y DIVULGANDO ENTRE AFILIADOS LA CONVOCATORIA PARA QUE SE INSCRIBIERAN GRATUITAMENTE EN LOS CURSOS.

EN LA VIGENCIA 2025 SE ADELANTARON ESTUDIOS PREVIOS Y PROCESO DE CONTRATACION Y SE ESTAN REALIZANDOO LAS CAPACITACIONES CON LA UNIVERSIDAD DE CUNDINAMARCA, EFECTUANDO LAS PREINSCRIPCIONES EN LA CORPORACION  Y DIVULGANDO ENTRE AFILIADOS LA CONVOCATORIA PARA QUE SE INSCRIBIERAN GRATUITAMENTE EN LOS CURSOS.  DURANTE EL ME DE NOVIEMBRE SE ESPERA REALIZAR UNA NUEVA ENCUESTA DE NECESIDADES ENTRE LOS AFILIADOS PARA CONOCER SU PERCEPCION FRENTE A LAS CAPACITACIONES RECIBIDAS Y CONSULTAR TEMAS DE INTERES PARA NUEVAS CAPACITACIONES', 'LOS CURSOS DURANTE EL 2024 SE DESAROLLARON Y CULMINARON SATISFACTORIAMENTE.

LAS CAPACITACIONES DEL 2025 ESTAN EN DESARROLLO Y CULMINAN EN EL MES DE DICIEMBRE CON LA CERTIFICACION DE LOS ALUMNOS QUE APRUEBEN CONFORME A LOS REQUISITOS CORRESPONDIENTES', NULL, NULL, NULL, 'LOS CURSOS DE LA VIGENCIA 2025 ESTAN EN DESARROLLO Y FINALIZAN EN EL MES DE DICIEMBRE CON LA CERTIFICACION DE QUIENES LOS APROBARON CON EL 80% DE LA ASISTENCIA Y LA REALIZACION Y PRESENTACION DE LAS ACTIVIDADES EXIGIDAS EN CADA DIPLOMADO O CURSO', 3529, 'CORPORACION SOCIAL', 'MISIONALIDAD DE LA ENTIDAD', 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.6445248&isFromPublicArea=True&isModal=False

UNIVERSIDAD DE CUNDINAMARCA
https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.8781583&isFromPublicArea=True&isModal=False', NULL, 5.00, 400.00);
INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES (NULL, 'TODAS LAS PROVINCIAS', 'TODOS LOS MUNICIPIOS', 'CONCERTAR ALIANZAS ESTRATEGICAS CON ENTIDADES, EMPRESAS Y ESTABLECIMIENTOS DE EDUCACION TECNICA Y SUPERIOR, SALUD, COMERCIO, RECREACION, CULTURA, TURISMO Y GASTRONOMIA EN EL DEPARTAMENTO DE CUNDINAMARCA; PARA BRINDAR A LOS AFILIADOS DE LA CORPORACION SOCIAL DE CUNDINAMARCA Y SUS BENEFICIARIOS , DESCUENTOS ESPECIALES EN UN ABANICO DIVERSO DE ACTIVIDADES PARA SU BIENESTAR.', 'BIENESTAR AFILIADOS', 'ALIANZAS ESTRATEGICAS - DESCUENTOS Y BENEFICIOS PARA ALIADOS Y SUS BENEFICIARIOS.', 'DURANTE LA VIGENCIA 2024 SE ESTABLECIERON MAS DE 80 CONTACTOS PARA BUSCAR ESTABLECIMIENTOS QUE BRINDEN BENEFICIOS A LOS AFILIADOS DE LA CORPORACION SOCIAL DE CUNDINAMARCA Y SU NUCLEO FAMILIAR.

DURANTE LA VIGENCIA DEL 2025 SE HAN FIRMADO 25 ALIANZAS ESTRATEGICAS, PARA BENEFICIAR CON DESCUENTOS A LOS AFILIADOS Y SUS BENEFICIARIOS,  DE LA CORPORACION SOCIAL DE CUNDINAMARCA CON LAS SIGUIENTES EMPRESAS, INSTITUCIONES Y ENTIDADES TANTO DEL SECTOR PUBLICO COMO DEL SECTOR  PRIVADO: UNIEMPRESARIAL, BRIGADAS COLOMBIA, CUPON APP, DMF MEDICS, UNIAGRARIA, BRITISH ACADEMY, PARQUE LA CHORRERA,  INTEGRAL HEALT, UNICERVANTES, IN SER, SIE SPA, CORPORACION UNIVERSITARIA IBEROAMERICANA, CORPORACION UNIFICADA NACIONAL DE EDUCACION SUPERIOR, UNIVERSIDAD COOPERATIVA DE COLOMBIA, EAN ESCUELA DE ADMINISTRACION DE NEGOCIOS, UNIASTURIAS, IFESE TECNICOS LABORALES, ENSEÑARTE PRIMARIA Y BACHILLERATO PARA ADULTOS, UNIGERMANA, CONSTRUCTORA DAR HOGAR, ALFAGRES, LA CASONA, CORPOCHINGAZA, TECNIRINES DE LA SABANA Y UNIMINUTO.', NULL, 'ALIANZAS ESTRATEGICAS:', NULL, NULL, NULL, NULL, 'ALTA', 'EN CURSO', 2824563097.00, NULL, NULL, NULL, NULL, NULL, 'CORPORACION SOCIAL DE CUNDINAMARCA - CSC', 'UNIEMPRESARIAL, BRIGADAS  COLOMBIA, CUPON APP, DMF MEDICS, UNIAGRARIA, BRITISH ACADEMY, PARQUE LA CHORRERA, INTEGRAL HEALT, UNICERVANTES, IN SER, SIE SPA, CORPORACION UNIVERSITARIA IBEROAMERICANA, CORPORACION UNIFICADA NACIONAL DE EDUCACION SUPERIOR, UNIVERSIDAD COOPERATIVA DE COLOMBIA, EAN ESCUELA DE ADMINISTRACION DE NEGOCIOS, UNIASTURIAS, IFESE TECNICOS LABORALES, ENSEÑARTE PRIMARIA Y BACHILLERATO PARA ADULTOS, UNIGERMANA, CONSTRUCTORA DAR HOGAR, ALFAGRES, LA CASONA, CORPOCHINGAZA, TECNIRINES DE LA SABANA Y UNIMINUTO.', NULL, NULL, 'AUNAR ESFUERZOS INSTITUCIONALES PARA DESARROLLAR ACCIONES CONJUNTAS EN TEMAS DE INTERES RECIPROCO, ASI COMO EN OTRAS FORMAS DE COLABORACION Y COOPERACION MUTUA,  QUE CONTRIBUYAN AL CUMPLIMIENTO DE LOS OBJETIVOS MISIONALES DE AMBAS ENTIDADES.', '3419563097', 'ENTREGAN A LOS AFILIADOS Y SU NUCLEO FAMILIAR DESCUENTOS EN LOS PRODUCTOS O SERVICIOS OFRECIDOS QUE OSCILAN ENTRE EL 10% Y EL 50% DEPENDIENDO DEL ESTABLECIMIENTO, TIPO DE SERVICIO O TEMPORADA', NULL, NULL, 'SE INICIO EN EL ULTIMO TRIMESTRE DEL 2024 ESTABLECIENDO CONTACTO CON DIVERSOS ESTABLECIMIENTOS DE DIFERENTES SECTORES, OBTENIENDO  RESPUESTA POSITIVA E INTENCION DE ESTABLECER LAS ALIANZAS POR PARTE DE BRIGADAS COLOMBIA, PARQUE LA CHORRERA, PARQUE CHINGAZA, PARQUES DE LA CAR E INTEGRAL HEALT

EN LA VIGENCIA 2025 SE HAN FIRMADO 25 ALIANZAS, UNA DE ELLAS, CAVES, INCLUYE OCHO (8) INSTITUCIONES EDUCATIVAS TALES COMO (CORPORACION UNIVERSITARIA IBEROAMERICANA, CORPORACION UNIFICADA NACIONAL DE EDUCACION SUPERIOR, UNIVERSIDAD COOPERATIVA DE COLOMBIA, EAN ESCUELA DE ADMINISTRACION DE NEGOCIOS, UNIASTURIAS, IFESE TECNICOS LABORALES, ENSEÑARTE PRIMARIA Y BACHILLERATO PARA ADULTOS, UNIGERMANA) CON OTRAS EN EL SECTOR EDUCATIVO Y TAMBIEN EN SECTORES COMO SALUD, RECREACION, CONSTRUCCION Y SERVICIO AUTOMOTRIZ.', 'POR PARTE DEL AREA DE SISTEMAS Y LA OFICINA DE ATENCION AL CLIENTE ESTAN TRABAJANDO EN EL DISEÑO DE UN CODIGO QR O DE UN ACCESO WEB, PARA QUE LOS ESTABLECIMIENTOS ALIADOS VALIDEN QUE QUIEN SOLICITA EL DESCUENTO EFECTIVAMENTE ES AFILIADO DE LA CORPORACION SOCIAL O PERTENECE A SU NUCLEO FAMILIAR Y  QUE SU ESTADO DE CUENTA NO PRESENTA MORA ALGUNA.

POR OTRA PARTE, SE ESPERA CAPTAR NUEVOS ALIADOS QUE TENGAN COBERTURA NACIONAL O DEPARTAMENTAL O QUE ESTEN UBICADOS EN LOS MUNICIPIOS PARA TENER LA MAYOR COBERTURA DEPARTAMENTAL.', NULL, NULL, NULL, 'SE TRATA DE UN PROCESO NUEVO QUE BUSCA BENEFICIOS A SUS AFILIADOS Y  SU NUCELO FAMILIAR.', 3530, 'CORPORACION SOCIAL', 'MISIONALIDAD DE LA ENTIDAD', NULL, NULL, 6.00, NULL);
INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES (NULL, 'TODAS LAS PROVINCIAS', 'TODOS LOS MUNICIPIOS', 'FIDELIZAR A LOS AFILIADOS A TRAVES DE LA DIFUSION DE LOS PROGRAMAS DE BIENESTAR, MOTIVANDO EL SENTIDO DE PERTENENCIA POR LA CSC; CON LA ENTREGA DE INCENTIVOS, ELEMENTOS CORPORATIVOS Y LA PRESENCIA DE ASESORES COMERCIALES EN LAS REGIONES DE CUNDINAMARCA, PARA ORIENTAR EL PORTAFOLIO DE SERVICIOS DE LA CORPORACION.', 'INCENTIVOS', 'DESARROLLO DE INCENTIVOS, PIEZAS PROMOCIONALES Y CAPACITACIONES PARA LOS AFILIADOS DE LAS CSC Y SUS BENEFICIARIOS.', 'DURANTE EL 2025, SE HAN ENTREGADO KITS DE PRIMEROS AUXILIOS, KIT DE LIBROS Y ANCHETAS, A AFILIADOS Y BENEFICIARIOS QUE ASISTIERON DEBIDAMENTE A LOS CURSOS DE FORMACION OFERTADOS EN LA VIGENCIA DE 2024 POR LA CSC; DE LA SIGUIENTE MANERA: DURANTE EL MES DE MARZO: 4 KITS DE EMERGENCIAS, 4 KITS DE LIBROS. ABRIL: 5 KITS DE EMERGENCIAS, 9 KITS DE LIBROS. MAYO: 2 ANCHETAS, 4 KITS DE EMERGENCIAS, 1 KIT DE LIBROS. JUNIO: 1 KIT DE EMERGENCIAS. SEPTIEMBRE: 1 KIT DE LIBROS. PARA UN TOTAL DE 31 INCENTIVOS ENTREGADOS.', NULL, 'IMPLEMENTACION Y DESARROLLO DE INCENTIVOS, PIEZAS PROMOCIONALES Y CAPACITACIONES PARA LOS AFILIADOS DE LAS CSC Y SUS BENEFICIARIOS.', NULL, NULL, NULL, NULL, 'ALTA', 'EN CURSO', 2484900000.00, NULL, NULL, NULL, NULL, 'RECURSOS PROPIOS', 'CORPORACION SOCIAL DE CUNDINAMARCA - CSC', 'FONDO DE DESARROLLO DE PROYECTOS  DE CUNDINAMARCA -FONDECUN', 'CONTRATO INTERADMINISTRATIVO', NULL, '“GERENCIA INTEGRAL PARA EL DESARROLLO DE LA PLANIFICACION OPERACION DEL PROYECTO PARA LA SELECCION DE INCENTIVOS Y PIEZAS PROMOCIONALES PARA LOS AFILIADOS DE LA” CSC “Y SUS BENEFICIARIOS, EN EL MARCO DEL CONVENIO No. 24-059 DE 2024, SUSCRITO CON FONDECUN, CON EL FIN DE LOGRAR LA FIDELIZACION Y CAPTACION DE NUEVOS AFILIADOS A LA ENTIDAD GENERANDO UN IMPACTO SOCIAL EN LA COMUNIDAD”.', '0', '31 INCENTIVOS ENTREGADOS.', NULL, NULL, 'ENTREGA DE  DIFERENTES KITS,LIBROS,ANCHETAS A AFILIADOS Y BENEFICIARIOS QUE ASISTIERON DEBIDAMENTE A LOS CURSOS DE FORMACION', NULL, NULL, NULL, NULL, 'DURANTE EL 2025, SE HAN ENTREGADO KITS DE PRIMEROS AUXILIOS, KIT DE LIBROS Y ANCHETAS, A AFILIADOS Y BENEFICIARIOS QUE ASISTIERON DEBIDAMENTE A LOS CURSOS DE FORMACION OFERTADOS EN LA VIGENCIA DE 2024 POR LA CSC; DE LA SIGUIENTE MANERA: DURANTE EL MES DE MARZO: 4 KITS DE EMERGENCIAS, 4 KITS DE LIBROS. ABRIL: 5 KITS DE EMERGENCIAS, 9 KITS DE LIBROS. MAYO: 2 ANCHETAS, 4 KITS DE EMERGENCIAS, 1 KIT DE LIBROS. JUNIO: 1 KIT DE EMERGENCIAS. SEPTIEMBRE: 1 KIT DE LIBROS. PARA UN TOTAL DE 31 INCENTIVOS ENTREGADOS.', 3531, 'CORPORACION SOCIAL', 'MISIONALIDAD DE LA ENTIDAD', 'https://community.secop.gov.co/Public/Tendering/ContractNoticePhases/View?PPI=CO1.PPI.40660174&isFromPublicArea=True&isModal=False', NULL, 10.00, 10.00);
INSERT INTO public.compromisos (codigo, provincia, municipio, compromiso_especifico, tema, subtema, detalle_especifico, meta_del_plan_de_desarrollo, descripcion_meta_producto, se_dara_cumplimiento_al_compromiso, dispone_del_presupuesto, el_compromiso_fue_modificado, nuevo_compromiso, prioridad, estado, valor_total, aporte_departamento, aporte_municipio, aporte_nacion, otro_aporte, fuente_cofinanciacion, entidad_lider, entidades_aliadas, tipo_documento, numero_documento, objeto_documento, valor_documento, bien_o_servicio_entregado, fecha_estimada_inicio, fecha_estimada_finalizacion, accion_adelantada, acciones_pendientes, se_requiere_apoyo_despacho, dificultades, alternativas_de_solucion, observaciones, id, entidad, obligacion_contraida, link_secop, georeferenciacion, avance_fisico, avance_financiero) OVERRIDING SYSTEM VALUE VALUES (NULL, 'TODAS LAS PROVINCIAS', 'TODOS LOS MUNICIPIOS', 'FORTALECER LAS COMPETENCIAS DIGITALES DE LOS AFILIADOS Y SUS FAMILIAS.
ENTREGAR TABLETS PERSONALIZADAS CON CONTENIDO EDUCATIVO.
PROMOVER LA INCLUSION DIGITAL Y EL APRENDIZAJE CONTINUO.
CERRAR BRECHAS DIGITALES Y GARANTIZAR ACCESO EQUITATIVO A LAS TIC.
CONTRIBUIR AL DESARROLLO SOCIAL Y ECONOMICO SOSTENIBLE EN CUNDINAMARCA, ALINEADO AL PLAN DE DESARROLLO DEPARTAMENTAL.', 'HERRAMIENTA TECNOLOGICA', 'INNOVACION TECNOLOGICA E ININCLUSION DIGITAL', 'PROPORCIONA LA ENTREGA GRATUITA DE TABLETS PERSONALIZADAS CON CONTENIDO EDUCATIVO Y HERRAMIENTAS TECNOLOGICAS. ESTE PROYECTO PROMUEVE LA APROPIACION TECNOLOGICA, FACILITA EL APRENDIZAJE CONTINUO EN EL ENTORNO FAMILIAR Y CONTRIBUYE A CERRAR LAS BRECHAS DIGITALES, POTENCIANDO EL ACCESO EQUITATIVO A LAS TIC Y FAVORECIENDO EL DESARROLLO SOCIAL Y ECONOMICO SOSTENIBLE EN EL DEPARTAMENTO.', NULL, 'DIRIGIDO A LOS AFILIADOS ACTIVOS DE LA CORPORACION SOCIAL DE CUNDINAMARCA Y SUS NUCLEOS FAMILIARES, CON ENFASIS EN POBLACIONES CON BARRERAS SOCIALES, ECONOMICAS O TERRITORIALES QUE LIMITAN SU ACCESO A TECNOLOGIA', NULL, NULL, NULL, NULL, 'ALTA', 'EN CURSO', 225000000.00, NULL, NULL, NULL, NULL, 'RECURSOS PROPIOS', 'CORPORACION SOCIAL DE CUNDINAMARCA - CSC', 'FONDO DE DESARROLLO DE PROYECTOS  DE CUNDINAMARCA -FONDECUN', 'CONTRATACION DIRECTA', NULL, '“GERENCIA INTEGRAL PARA EL FORTALECIMIENTO DE HERRAMIENTAS TECNOLOGICAS PARA LOS AFILIADOS DE LA CORPORACION SOCIAL DE CUNDINAMARCA Y SUS BENEFICIARIOS ENCAMINADO A LA FORMACION EN COMPETENCIAS DIGITALES”', '$1.666.666.667', 'SE ENTREGARAN 1.200 TABLET', NULL, NULL, 'SE REALIZARON DIFERENTES CAPACITACIONES A LOS AFILIADOS CON EL FIN DE SER UN REUICITO PARA LA ENTREGA DE LA TABLET.', 'ENTREGA DE LAS TABLETS A LOS AFILIADOS QUE HAYAN REALIZADO LAS DIFERNETES CAPACITACIONES, ESTAS TABLETS SE ENTREGARAN EN EL MARCO DE CUNDINAMARCA FEST DEL 13 AL 16 DE NOVIEMBRE.', NULL, NULL, NULL, 'SE REALIZO UNA CONVOCATORIA PUBLICA MEDIANTE CANALES DIGITALES Y ENCUESTAS.
RECEPCION Y DEPURACION DE 2.965 ENCUESTAS, DE LAS CUALES 2.660 FUERON VALIDAS.
